// Starlight route middleware. The pages generated by starlight-openapi have
// no description: give each one, so that search engines and link previews
// get a summary in French like every other page. Their overview pages are
// titled « Overview », which `lang` cannot mark in <title>: they take
// Starlight's French label instead, in the sidebar, the table of contents and
// the pagination links too.
import { defineRouteMiddleware, type StarlightRouteData } from '@astrojs/starlight/route-data';
import { SITE_NAME } from './lib/meta.ts';
import { OVERVIEW } from './lib/reference.ts';
import { REFERENCE_PATH } from './lib/site.ts';

const TAGS_PATH = `${REFERENCE_PATH}operations/tags/`;

/** The description of a generated reference page, from its path and title. */
function referenceDescription(pathname: string, title: string): string {
  const api = `l'API ${SITE_NAME}`;
  let subject: string;
  if (pathname === REFERENCE_PATH) subject = `Référence de ${api}`;
  else if (pathname.startsWith(TAGS_PATH)) {
    const tag = decodeURIComponent(pathname.slice(TAGS_PATH.length).replace(/\/$/, ''));
    subject = `Référence des opérations « ${tag} » de ${api}`;
  }
  // An operation page is titled with the operation's summary.
  else subject = `${title} : référence de ${api}`;
  return `${subject}, générée depuis son contrat OpenAPI.`;
}

type SidebarEntry = StarlightRouteData['sidebar'][number];

/** Renames the sidebar links labelled `OVERVIEW`, in every group. */
function renameOverview(entries: SidebarEntry[], label: string) {
  for (const entry of entries) {
    if (entry.type === 'group') renameOverview(entry.entries, label);
    else if (entry.label === OVERVIEW) entry.label = label;
  }
}

/** Retitles an overview page: heading, table of contents, <title> and og:title. */
function retitleOverview(route: StarlightRouteData, label: string) {
  if (route.entry.data.title !== OVERVIEW) return;
  route.entry.data.title = label;
  for (const item of route.toc?.items ?? []) {
    if (item.text === OVERVIEW) item.text = label;
  }
  for (const tag of route.head) {
    if (tag.tag === 'title' && tag.content?.startsWith(`${OVERVIEW} `)) {
      tag.content = label + tag.content.slice(OVERVIEW.length);
    } else if (tag.attrs?.property === 'og:title' && tag.attrs.content === OVERVIEW) {
      tag.attrs.content = label;
    }
  }
}

export const onRequest = defineRouteMiddleware(async (context, next) => {
  // starlight-openapi's own route middleware, which builds the sidebar and
  // the table of contents, runs after this one.
  await next();
  const route = context.locals.starlightRoute;
  const overview = context.locals.t('tableOfContents.overview');
  renameOverview(route.sidebar, overview);
  for (const link of [route.pagination.prev, route.pagination.next]) {
    if (link?.label === OVERVIEW) link.label = overview;
  }
  if (!context.url.pathname.startsWith(REFERENCE_PATH)) return;

  retitleOverview(route, overview);
  if (route.head.some((tag) => tag.tag === 'meta' && tag.attrs?.name === 'description')) return;

  const content = referenceDescription(context.url.pathname, route.entry.data.title);
  route.head.push(
    { tag: 'meta', attrs: { name: 'description', content } },
    { tag: 'meta', attrs: { property: 'og:description', content } },
  );
});
